library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

-- Uncomment the following library declaration if using
-- arithmetic functions with Signed or Unsigned values
--use IEEE.NUMERIC_STD.ALL;

-- Uncomment the following library declaration if instantiating
-- any Xilinx primitives in this code.
--library UNISIM;
--use UNISIM.VComponents.all;

entity OUTPUT is
    Port ( STATE_IN : in  STD_LOGIC_VECTOR (3 downto 0);
				CLK : IN STD_LOGIC;
				CORRECT_IN : STD_LOGIC;
				CORRECT_SUM : STD_LOGIC_VECTOR(7 DOWNTO 0);
           TEXT_OUTPUT : in  STD_LOGIC_VECTOR (815 downto 0);
			  TEXT_FOR_DISPLAY : OUT STD_LOGIC_VECTOR (815 downto 0);
			  READY : OUT STD_LOGIC);
			  
end OUTPUT;

architecture Behavioral of OUTPUT is
	signal actual_text : STD_LOGIC_VECTOR(815 downto 0) := (others => '0');
	signal count : integer:=0;
begin

 process(clk,STATE_IN,CORRECT_IN,TEXT_OUTPUT )

    begin
	 if count = 14 then
					actual_text<= (others => '0');
					
					actual_text<="";
	 
	 end if;
        if rising_edge(clk) and count<14 then

					 
                case STATE_IN is
							--stan pocztkowy po uruchomieniu
                    when "1000" => 
						  READY<='1';
					actual_text<= (others => '0');
					
					actual_text<="";

						  
						  when "0100" => 
						   READY<='1';
							actual_text <= TEXT_OUTPUT;
							count<=count+1;
						  
						  
                    when "0010" => 
						  READY<='1';
							actual_text<= (others => '0');
					
					actual_text<="";
						  
						  
                    when "0001" => 
						  READY<='1';
						  
						   if CORRECT_IN = '1' THEN

							actual_text<= (others => '0');
					
					actual_text<="";
						  
						  else 
							actual_text<= (others => '0');
					
					actual_text<="";
						  
						  end if;

						  
                    when others =>
						  READY<='0';

                end case;
		

            end if;

		  
		  
		  
    end process;
TEXT_FOR_DISPLAY<=actual_text;

end Behavioral;

